CREATE DEFINER=`root`@`localhost` PROCEDURE `GetCustomerInvoiceHistory`(IN custID INT)
BEGIN
    SELECT
        Invoice.InvoiceNo,
        Invoice.InvoiceDate,
        Invoice.InvoiceType,
        Invoice.Status,
        SUM(InvoiceLine.Quantity * InvoiceLine.UnitPrice) AS InvoiceTotal
    FROM Invoice
    JOIN InvoiceLine ON Invoice.InvoiceNo = InvoiceLine.InvoiceNo
    WHERE Invoice.CustomerID = custID
    GROUP BY
        Invoice.InvoiceNo,
        Invoice.InvoiceDate,
        Invoice.InvoiceType,
        Invoice.Status
    ORDER BY Invoice.InvoiceDate DESC;
END ;;
DELIMITER ;
